export type NewYearGuideLink = { title: string; href: string; note: string };
export type NewYearGuideFaq = { question: string; answer: string };
export type NewYearCityGuide = {
  heading: string;
  intro: string;
  sections?: Array<{ heading: string; text: string }>;
  recommendations: NewYearGuideLink[];
  faq?: NewYearGuideFaq[];
};

