export function getNewYearRegionGuide(region: string): string {
  return NEW_YEAR_REGION_GUIDES[region]
    || `Новогодняя афиша региона «${region}» формируется из опубликованных событий в населённых пунктах, где есть доступные сеансы. Сначала выберите город и проверьте площадку в карточке: состав и география подборки меняются вместе с каталогом.`;
}

